"""Layer 15 MLP hidden unit 4038, read through its down_proj component.

The component's input direction is almost exactly this one MLP hidden unit (weight
0.94 on unit 4038, about 0.04 on any other), so its activation is that unit's value
scaled by a constant. The unit is mostly small noise. Its readable tendencies:

  * up, strongly, on assertion code: tokens containing "assert" (assert, assertTrue);
  * up on an auxiliary or modal right after a pronoun or a negation ("You're",
    "that must", "It's not", "you really"), and mildly up on any word right after
    "you"/"your";
  * down on code declarations and test-runner output ("const", "def", "var", "let",
    "fn", "void", "Test", "test", "RUN", "PASS", ".py", "::");
  * slightly down on digits and on punctuation.

Everything else predicts 0. Each number is the group's mean activation on training
rows (rounded), so the program is those group means, nothing more. It explains
under 1% of the variance: the unit's activation is mostly context noise that no
word-level rule captures.
"""

READS = ()

PRONOUNS_AND_NEGATIONS = {"you", "your", "i", "we", "they", "he", "she", "it", "that", "this",
                          "not", "n't", "'t", "’t", "never", "no"}
YOU = {"you", "your"}
AUXILIARIES = {"would", "could", "should", "must", "can", "will", "might", "know", "want",
               "really", "just", "right", "be", "going", "gonna", "need",
               "'re", "'s", "'t", "n't", "’re", "’t", "’s", "’ll", "'ll", "'d", "’d"}
CODE_WORDS = {"const", "def", "var", "let", "fn", "void", "int", "return", "private", "public",
              "readonly", "string", "func", "static", "class", "struct", "import", "self"}
TEST_TOKENS = {"test", "tests", "run", "pass", "passed", "fail", "::", ".py", "===", "github"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if "assert" in word:
        return carry, 1.9
    if word in CODE_WORDS or word in TEST_TOKENS:
        return carry, -0.33
    if word in AUXILIARIES and before in PRONOUNS_AND_NEGATIONS:
        return carry, 0.19
    if before in YOU:
        return carry, 0.085
    if word.isdigit():
        return carry, -0.08
    if word and not any(ch.isalnum() for ch in word):
        return carry, -0.03
    return carry, 0.0

"""Layer 15, MLP hidden unit 4051 (component p-82af68dd@100000/layers.15.mlp.down_proj:4051).

What it is: this component is the MLP hidden unit 4051 of layer 15, read through its
down-projection direction (about two-thirds of its read vector is that unit). It is quiet on
most tokens, and when it fires it fires mostly negative, in a few recognisable places:

  * citation and cross-reference markup: the link-attribute token "-type" in
    "(#fig1){ref-type=...}", the link openers "[@" and "](", "{ref", "#fig", and the
    "Introduction"/"Abstract" headings of papers;
  * the token right after a reference word, as in "Figure 2", "Table 1", "Fig. 4",
    "U.S. Pat. No." (the space or punctuation that leads into the number);
  * a footnote star followed by a digit in legal text ("*1" ... ).

Weakly positive: the role word "user" after "<|im_start|>", and "<|im_end|>" ending a chat turn.

Everything else predicts 0. The values are rough conditional means measured on training text;
this captures only a small part of the variance, because ordinary-text activations are diffuse
and not predicted by the current token or the few before it.
"""

READS = ()

CITATION_MARKUP = {"-type", "[@", "](", "{ref", "#fig", "pone", "Introduction", "Abstract"}
REFERENCE_WORDS = {"Figure", "Figures", "Fig", "Table", "Tables", "Pat"}
CHAT_POSITIVE = {"user", "<|im_end|>"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    if word in CITATION_MARKUP:
        value = -4.0
    elif before in REFERENCE_WORDS:
        value = -3.0
    elif word == "{\"":
        value = -0.8
    elif word.isdigit() and before == "*":
        value = -1.0
    elif word in CHAT_POSITIVE:
        value = 0.6
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP hidden unit 4054 (this component): a "derivation step is coming" detector.

The component is the MLP hidden unit 4054 of layer 15 (its down-projection vector is almost
entirely that one unit). It is positive at the few tokens where written-out reasoning turns
into a calculation:

- a connective that opens a derivation step: "So", "Thus", "Therefore", "hence" (about +1.5);
- a colon and a blank line that introduce an equation (about +2);
- an implication arrow, "⇒" or "⊢" (about +4);
- a token that opens a displayed or inline formula: " $$", " \\(", "$\\", "${", "display",
  "style" (about +2.5).

Everywhere else the unit is near zero with mixed sign, so the program predicts 0. This explains
a few percent of its variance: the bulk of the activation is diffuse and sign-varying, and
no simple concept we tried (token class, math density, position) captured it.

The program is stateless and reads only the newest token.
"""

READS = ()

# Connectives that open a derivation step, with or without a leading space.
CONNECTIVES = {"so", "thus", "therefore", "hence"}

# Tokens that open a displayed or inline formula, or a LaTeX display environment.
FORMULA_OPENERS = {" $$", " \\(", "\\(", "$\\", "${", "display", "style"}

# Implication arrows.
IMPLIES = {"⇒", "⊢", "Rightarrow", "Longrightarrow"}

# A line break after a colon, the way a formula is introduced.
INTRO_BREAKS = {":\n\n", "):\n\n", "：\n\n"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip().lower() in CONNECTIVES:
        return carry, 1.5
    if token.strip() in IMPLIES:
        return carry, 4.0
    if token in FORMULA_OPENERS:
        return carry, 2.5
    if token in INTRO_BREAKS:
        return carry, 2.0
    return carry, 0.0

"""Layer 15 MLP down_proj, component 4061: a subject-pronoun detector, written negative.

What it does: the component goes negative on the personal pronoun that starts a clause's
subject, and on the auxiliary verb right after it. It is strongest on third-person subjects
(it, they, he, she, and their Chinese forms), weaker on I, you, we, and weaker still on
object and possessive pronouns (them, its, their, his, her, him). Its size depends on what
comes before the pronoun: most negative right after a clause-joining word (and, but, so,
when, that, if, ...), less after sentence punctuation, least mid-clause after a plain word.
A finite auxiliary (is, was, can, ...) right after a subject pronoun is mildly negative, and
one right after a clause-joining word is more negative. Common function words (the, a, of,
to, and, or, but, not) are slightly positive, and everything else is 0.

Why: the largest negative values sit on subject pronouns that open a clause, and on the verb
that follows them. Most of the remaining variance is spread over many ordinary tokens with
no simple rule, so this program explains the readable part only.
"""

READS = ()

THIRD_SUBJECT = {"it", "they", "he", "she", "他", "她", "它", "他们", "她们", "它们", "они", "он",
                 "она", "sie", "il", "elle"}
FIRST_SECOND_SUBJECT = {"i", "you", "we", "我", "你", "我们", "你们", "您"}
OBJECT_OR_POSSESSIVE = {"them", "its", "their", "his", "her", "him"}
FINITE_AUX = {"is", "are", "was", "were", "be", "am", "can", "will", "has", "had", "would",
              "could", "may", "might", "must", "does", "did", "being"}
CLAUSE_JOINERS = {"and", "but", "so", "when", "that", "if", "because", "where", "as", "then",
                  "while", "since", "though"}
SENTENCE_START = {"", ".", "!", "?", ";", ":", "(", '"'}
SUBJECT_PRONOUNS = THIRD_SUBJECT | FIRST_SECOND_SUBJECT
FUNCTION_WORDS = {"the", "a", "of", "to", "and", "or", "but", "not"}


def subject_value(word, prev):
    """Value of a subject pronoun, by what precedes it."""
    if prev in CLAUSE_JOINERS:
        strength = 3.3 if word in THIRD_SUBJECT else 1.5
    elif prev in SENTENCE_START:
        strength = 2.1 if word in THIRD_SUBJECT else 0.8
    elif prev == ",":
        strength = 1.6 if word in THIRD_SUBJECT else 0.5
    else:
        strength = 1.1 if word in THIRD_SUBJECT else 0.3
    return -strength


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    if word in SUBJECT_PRONOUNS:
        value = subject_value(word, prev)
    elif word in OBJECT_OR_POSSESSIVE:
        value = -0.9
    elif word in FINITE_AUX:
        if prev in SUBJECT_PRONOUNS:
            value = -0.5
        elif prev in CLAUSE_JOINERS:
            value = -2.0
    elif word in FUNCTION_WORDS:
        value = 0.2
    return carry, float(value)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:4071 (layer 15 MLP down_proj, rank-one piece).

What it does: its activation is near zero on most tokens (mean about -0.035), with a weak,
diffuse negative dip on the word that follows a coordinating conjunction. The dip is
strongest after "or" (and its translations), and deepest when the word after "or" starts a
new verb phrase (an auxiliary or modal such as "are", "have", "will"). After "and" the dip is
smaller. Code access keywords ("public", "static", "private") give a moderate dip too.

This program predicts that pattern from the two most recent tokens. It explains very little
of the activation: the activation is spread over many tokens, and no short rule captures it.
The largest negative values, down to about -13, are not reproduced by these rules.
"""

READS = ()

MEAN = -0.035
OR_WORDS = {"or", "oder", "ou", "или", "và", "أو"}
AND_WORDS = {"and", "und", "et", "и", "و"}
CODE_WORDS = {"public", "static", "private"}
AUX = {"are", "is", "be", "have", "has", "had", "will", "would", "may", "can", "could",
       "should", "must", "might", "was", "were", "do", "does"}


def step(carry, prefix, upstream):
    # Start of a document: no previous word, so predict the mean.
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, MEAN
    before = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if before in OR_WORDS:
        return carry, -2.0 if word in AUX else -0.4
    if before in AND_WORDS:
        return carry, -0.2
    if before in CODE_WORDS:
        return carry, -0.4
    return carry, MEAN

"""Layer 15 MLP down-projection component 4080.

It is negative where the text is labelling or numbering something (an item of a list, a
figure, table, test or step, an appendix or option letter, a citation number, a line
number), and near zero elsewhere. Digits carry most of its variance: a digit that
names an item is strongly negative, a digit that starts a line or follows an opening
bracket is moderately negative, other digits are mildly negative (0 and 1 least).
"""
import re

READS = ()

ITEM_WORDS = {
    "figure", "fig", "figs", "table", "test", "question", "case", "example", "step",
    "chapter", "equation", "article", "page", "part", "section", "appendix", "exhibit",
    "option", "item", "exercise", "problem", "lemma", "theorem", "line", "rule", "clause",
}
MONTHS = {"january", "february", "march", "april", "may", "june", "july", "august",
          "september", "october", "november", "december"}
ORDINALS = {"first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth"}
LABEL = re.compile(r"\(?([A-Za-z]|[ivxIVX]+)\)?")


def _previous(toks, docs, i):
    """The nearest earlier non-blank token of this document, and whether token i starts a line."""
    j = i - 1
    while j >= 0 and docs[j] == docs[i] and toks[j].strip() == "" and "\n" not in toks[j]:
        j -= 1
    prev = toks[j].strip().lower() if j >= 0 and docs[j] == docs[i] else ""
    k = i - 1
    while k >= 0 and docs[k] == docs[i] and toks[k].strip() == "" and "\n" not in toks[k]:
        k -= 1
    line_start = k < 0 or docs[k] != docs[i] or "\n" in toks[k]
    return prev, line_start


def step(carry, prefix, upstream):
    toks, docs = prefix.token_strings, prefix.document_ids
    i = len(toks) - 1
    word = toks[i].strip()
    prev, line_start = _previous(toks, docs, i)
    if word.isdigit():
        if prev in ITEM_WORDS or prev.endswith("["):
            return carry, -5.3      # "Figure 3", "Test 4:", "[1" citations
        if prev == "(":
            return carry, -1.5
        if line_start:
            return carry, -2.7      # line numbers and list enumerators
        if word == "0":
            return carry, -0.3
        if word == "1":
            return carry, -0.9
        return carry, -1.9
    if LABEL.fullmatch(word) and (prev in ITEM_WORDS or prev in ("(", "[")):
        return carry, -2.0          # "Appendix F", "option B", "(d)"
    if word.lower() in MONTHS:
        return carry, -4.6
    if word.lower() in ORDINALS:
        return carry, -2.6
    if word == "":
        return carry, 0.2
    return carry, 0.0
